def count_free_rooms(n):
    count = 0
    for _ in range(n):
        p, q = map(int, input().split())
        if q - p >= 2:
            count += 1
    return count

# Example usage:
n = int(input())
print(count_free_rooms(n))

def count_free_rooms(n, rooms):
    count = 0
    for p_i, q_i in rooms:
        if q_i - p_i >= 2:
            count += 1
    return count

# Example usage:
n = int(input())
rooms = [tuple(map(int, input().split())) for _ in range(n)]
print(count_free_rooms(n, rooms))

